package io.github.diodeme.ji.session.tree;

import java.util.List;
import java.util.Optional;

/** Atomic bridge between a canonical Session transition and an optional durable queued input. */
public interface SessionInputCoordinator {
    SessionDocument beginNextTurn(
            String sessionId, long expectedSessionRevision, OptionalInputTransition transition);

    Optional<SessionDocument> continueWithSteer(
            String sessionId, long expectedSessionRevision, RequiredInputTransition transition);

    @FunctionalInterface
    interface OptionalInputTransition {
        SessionDocument apply(SessionDocument document, Optional<QueuedInput> input);
    }

    @FunctionalInterface
    interface RequiredInputTransition {
        SessionDocument apply(SessionDocument document, QueuedInput input);
    }

    record QueuedInput(
            String itemId,
            String commandId,
            long acceptedSeq,
            String clientId,
            List<String> content,
            List<String> attachments) {
        public QueuedInput {
            if (itemId == null || itemId.isBlank() || commandId == null || commandId.isBlank()
                    || acceptedSeq < 1 || clientId == null || clientId.isBlank()) {
                throw new IllegalArgumentException("queued input identity is invalid");
            }
            content = List.copyOf(content);
            attachments = List.copyOf(attachments);
            if (content.isEmpty() && attachments.isEmpty()) {
                throw new IllegalArgumentException("queued input must contain content");
            }
        }
    }
}
